namespace Orbit.Application.Chat;

public static class HabitModelInstructions
{
    public const string WriteIntent = "Create or change account records only when the person requests that action. Coaching alone does not authorize a write. For a requested adjustment to an activity already tracked, use its existing habit ID instead of creating a duplicate of its purpose.";

    public const string Coaching = "For advice about making an activity easier, give one to three short practical lines without a preview or draft. A date or a possible checklist is context, not a request to change records. " + WriteIntent;

    public const string Schedule = "A Task is one-time: frequency_unit=OneTime in create tools, stored as null, with due_date and requested due_time. A dated event or single dated instruction is a Task unless repetition was requested. A Habit has Day, Week, Month or Year and a positive frequency_quantity. Daily weekdays require Day/1; is_flexible tracks a quantity within a window and cannot have weekdays. General items have no schedule, recurrence or avoid type. end_date is inclusive and only recurring items use it. A preparation that starts N days or hours before an event and continues until it is a Day/1 Habit: set due_date to the first local date and inclusive end_date to the event date. start_date is only the recurrence anchor and never replaces due_date. Keep a single dated action as a Task. For an activity lasting until a collection or other deadline, put its ending clock time in due_end_time, not due_time; omit due_time when its start was not specified. Never leave temporary preparation recurring indefinitely.";

    public const string Polarity = "Use is_bad_habit=true only for ongoing reduction or slip tracking, named for the behaviour itself: Fumar, Tomar multivitamínico, Smoking, Drinking soda. For quero parar de fumar or I want to drink less soda, choose that avoid form. A temporary or dated abstinence is a positive commitment, is_bad_habit=false, named Não tomar multivitamínico or Don't take multivitamins, once or within its explicit date range. Keep the requested action and negation in temporary commitment titles: don't go to Muay Thai becomes Don't go to Muay Thai, and não ir ao Muay Thai becomes Não ir ao Muay Thai. Don't take multivitamins must not become Stop taking multivitamins. For an activity described in prose, normalize spelling and casing without changing the action or negation: não ir pro muay thay becomes Não ir ao Muay Thai. Never replace these with Skip Muay Thai, Pular Muay Thai or a generic preparation label. Never combine an avoid type with a negated name: não, sem, parar de, evitar, don't, stop, avoid.";

    public const string Correction = "A correction is a patch: send only fields the person requested changing. Preserve every other field, including one-time status, dates, times, recurrence, end date, reminders, tags and checklist. Changing polarity never changes recurrence. Revise a pending preview instead of creating a duplicate.";

    public const string Titles = "Preserve a title the person quoted or named verbatim as an exact record title, including its language, spelling, accents, casing and dates. Never translate or rephrase that title, even when it differs from the request language. An activity described in prose is not an exact record title: preserve its action and negation while normalizing spelling, casing and proper names. For titles you compose, use the request language supplied for this turn. Apply this to create and update arguments, bulk items and nested sub-habits before preparing the approval preview. English examples and existing account titles are not language templates. Never rename an existing habit unless the person requested it.";

    public static string TitleLanguage(string? language) =>
        $"Write composed habit titles in {Common.LocaleHelper.GetAiLanguageName(language)}. {Titles}";

    public const string DisplayDates = "Use ISO YYYY-MM-DD only in machine date fields. Dates inside composed titles and descriptions use the person's locale, DD/MM/YYYY in pt-BR and MM/DD/YYYY in en-US. Preserve dates in titles the person supplied verbatim. Do not repeat the same date in ISO and local form.";

    public const string Batch = "For several creates in one request, call bulk_create_habits once with the entire set, including dated events and independent preparation commitments. Use its existing batch preview. Keep every supplied date and time, including past dates; an explicit past date is not missing input. Derive preparation dates from the supplied event date, not from today. When event dates, times and preparation offsets are supplied, propose the entire batch without asking for those values again. Preparation on different dates needs separate trackable items, rather than only the exam description. A failed item keeps its name and reason and remains editable and retryable.";

    public const string BrainDump = "When the person asks to organize one unstructured message into tasks and habits, prepare one combined approval preview with bulk_create_habits. Keep every actionable item from the message, with one-time tasks and recurring habits distinct. Resolve existing activities from the account index or query_habits, and pass habit_id on reused items rather than creating duplicates. Preserve existing fields unless a change was requested. Do not create task or habit group headings as account records. Reuse suggest_habits when additional habit ideas are requested; its editable drafts can supply the proposed habit fields, and existingHabitId becomes habit_id in the combined preview. Keep explicit tasks alongside those suggestions. A request to organize is permission to prepare a preview only. The person can approve, edit or reject the entire preview; nothing is saved before approval. Use at most one short sentence without figures, then the combined preview. All figures belong in the preview. Apply this equally to typed and transcribed messages in the current message's language.";

    public const string Routine = "Recommend routine structure from the destination's checklist and sub-habits, then the account's structure pattern. Honor an explicit placement choice. For an addition to an existing routine, keep parent_habit_id and omit placement for the server recommendation; the preview offers checklist_item, sub_habit and new_parent with a reason. A brand-new routine on an account with no structure defaults to one parent with sub_habits. A morning or evening routine implies Day/1 unless another cadence was requested; weekday wording uses Day/1 with the requested days. Keep the parent's requested time and each child's own time, including lights out by 11 in an evening routine as 23:00. Durations belong to their activities. A missing hour does not block a preview: omit due_time when no hour was given. Propose the inferred cadence in the approval preview so the person can edit it. Only ask when no usable preview can be proposed. These rules apply equally to rotina da manhã, rotina da noite and dias úteis.";

    public static string All => string.Join("\n\n", Coaching, Schedule, Polarity, Correction, Titles, DisplayDates, Batch, BrainDump, Routine);
}
